import numpy as np

def rx(a):
 c,s=np.cos(a),np.sin(a);return np.array([[1,0,0],[0,c,-s],[0,s,c]])
def ry(a):
 c,s=np.cos(a),np.sin(a);return np.array([[c,0,s],[0,1,0],[-s,0,c]])
def rz(a):
 c,s=np.cos(a),np.sin(a);return np.array([[c,-s,0],[s,c,0],[0,0,1]])
def orientation(g):
 theta=np.arctan2(g[0],-g[2]);roll=np.arctan2(-g[1],np.hypot(g[0],g[2]));return ry(theta)@rx(roll)
def feet(q):
 out=[]
 for side,start in [(1,0),(-1,5)]:
  a=q[start:start+5];R=rz(a[0]);p=np.array([0,side*.087,-.174])+R@np.array([.039,0,0]);R=R@rx(a[1]);p+=R@np.array([0,side*.116,0]);R=R@ry(a[2]);p+=R@np.array([0,0,-.4]);R=R@ry(a[3]);p+=R@np.array([0,0,-.4]);R=R@ry(a[4]);p+=R@np.array([.05,0,-.091]);out.append(p)
 return np.array(out)
def estimate(o):
 o=np.array(o);q=o[:19];dq=o[19:38];w=o[38:41];g=o[41:];R=orientation(g);p=feet(q);v=(feet(q+dq*.0001)-p)/.0001 + np.cross(w,p)
 return R@p.T, -R@v.T
if __name__=='__main__':
 import json
 o=json.load(open('/app/output/latest/meta.json'))['proprio']['now'];print('feet, velocity',estimate(o))
